export class Aabb2 {
	min: float2 = { x: 0, y: 0 };
	max: float2 = { x: 0, y: 0 };

	constructor(min: float2, max: float2) {
		this.min = min;
		this.max = max;
	}

	clone(): Aabb2 {
		return new Aabb2({ x: this.min.x, y: this.min.y }, { x: this.max.x, y: this.max.y });
	}

	contains(pos: float2) {
		return pos.x >= this.min.x && pos.x <= this.max.x && pos.y >= this.min.y && pos.y <= this.max.y;
	}

	get width(): number {
		return this.max.x - this.min.x;
	}
	get height(): number {
		return this.max.y - this.min.y;
	}

	size(): float2 {
		return sub2(this.max, this.min);
	}

	distSqToPoint(px: number, py: number) {
		let x = 0,
			y = 0;
		if (px < this.min.x) x = this.min.x - px;
		else if (px >= this.max.x) x = px - this.max.x;
		if (py < this.min.y) y = this.min.y - py;
		else if (py >= this.max.y) y = py - this.max.y;
		return x * x + y * y;
	}

	intersects(other: Aabb2) {
		return !(
			other.min.x >= this.max.x ||
			other.max.x <= other.min.x ||
			other.min.y >= this.max.y ||
			other.max.y <= other.min.y
		);
	}

	getWrappedData(pos: float2, wrapType: WrapType): { pos: float2; signedNearest: float2 } {
		const wrappedPos = { x: pos.x, y: pos.y };
		const signedNearest: float2 = { x: Infinity, y: Infinity };

		const size = this.size();
		const min = this.min;
		const max = this.max;

		// Adjust the target to be in the wrapped space based on wrap direction.
		if (wrapType === WrapType.WrapX || wrapType === WrapType.WrapXY) {
			wrappedPos.x = min.x + VoronoiUtils.posMod(pos.x - min.x, size.x);
			signedNearest.x = pos.x - min.x <= max.x - pos.x ? -(pos.x - min.x) : max.x - pos.x;
		}
		if (wrapType === WrapType.WrapY || wrapType === WrapType.WrapXY) {
			wrappedPos.y = min.y + VoronoiUtils.posMod(pos.y - min.y, size.y);
			signedNearest.y = pos.y - min.y <= max.y - pos.y ? -(pos.y - min.y) : max.y - pos.y;
		}

		return { pos: wrappedPos, signedNearest: signedNearest };
	}
}

export type WrapDistOptions =
	| { wrap?: typeof WrapType.None }
	| { wrap: typeof WrapType.WrapX; width: number }
	| { wrap: typeof WrapType.WrapY; height: number }
	| { wrap: typeof WrapType.WrapXY; width: number; height: number };

export interface PropertyRef<T> {
	get(): T;
	set(value: T): void;
	subscribe(listener: (newValue: T) => void): () => void;
}

export type WithOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;

export function getterSetter<T>(get: () => T, set: (newValue: T) => void): PropertyRef<T> {
	const listeners = new Set<(newValue: T) => void>();
	return {
		get: get,
		set: (newValue: T) => {
			set(newValue);
			listeners.forEach((listener) => listener(newValue));
		},
		subscribe: (listener) => {
			listeners.add(listener);
			return () => {
				listeners.delete(listener);
			};
		},
	};
}

export function propRef<TObj, TKey extends keyof TObj>(obj: TObj, key: TKey): PropertyRef<TObj[TKey]> {
	return getterSetter<TObj[TKey]>(
		() => obj[key],
		(value) => {
			obj[key] = value;
		},
	);
}

export function propArrayRef<TObj, TKey extends keyof TObj>(arr: TObj[], key: TKey): PropertyRef<TObj[TKey]> {
	return getterSetter<TObj[TKey]>(
		() => {
			if (arr.length === 0) {
				return 0 as TObj[TKey];
			}
			return arr[0][key];
		},
		(value) => {
			for (const obj of arr) {
				obj[key] = value;
			}
		},
	);
}

